-- =============================================================================
-- University of Nigeria, Nsukka - Faculty of Physical Sciences - Statistics
-- Course outlines transcribed from the departmental course handbook.
-- =============================================================================
-- Run in the Supabase SQL Editor. Safe to run more than once.
--
-- NOTE ON SEMESTERS: the handbook does not state them; the usual Nigerian
-- odd/even course-number convention is applied. Correct in the Table Editor
-- where UNN differs.
--
-- NOTE ON CREDIT UNITS: the source PDF right-aligns unit values, so they were
-- extracted as a per-page block and matched back by page order. One to check
-- against the printed handbook: STA 384 (Report on Industrial Training) comes
-- out at 12 units, which is high for a report -- it may belong to STA 382
-- (Practical on Industrial Training), currently at 3.
--
-- This file also carries the required ancillary, general-studies and elective
-- courses a Statistics student actually sits each semester, scoped to
-- this department so they appear on the student's own timetable — independent
-- rows from any same-code row filed under its own home department.
-- Source for the programme structure: the Department of Statistics' published undergraduate course module
-- Descriptions are reused, unedited, from this app's sibling UNN outline files
-- wherever the course code already exists there; courses with no verified
-- description anywhere (GSP, COS, BIO, ECO, engineering and language codes)
-- carry code/title/units/level/semester only, rather than an invented syllabus.
-- Electives are flagged by an "Elective." prefix on the description, since this
-- file's column list predates the is_elective column.
-- Only the Four-Year Standard Programme is followed, not the Three-Year
-- direct-entry or combined-honours variants.
-- =============================================================================

delete from public.course_outlines
 where institution = 'University of Nigeria, Nsukka'
   and department = 'Statistics';

insert into public.course_outlines
  (course_code, course_title, institution, faculty, department, level,
   semester, credit_units, description, topics, contributor_name)
values
  ('STA 111', 'Probability I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'first', 2, 'Elementary set theory. Techniques of counting, sample space and Events. Basic notions of probability, definition, axioms and laws. Simple conditional probability and independence.', '["Elementary set theory", "Techniques of counting, sample space and Events", "Basic notions of probability, definition, axioms and laws", "Simple conditional probability and independence"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 112', 'Probability II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'second', 2, 'One dimensional random variables, discrete and continuous: definition, moments and their distributions. Applications to Bernoulli, Binomial, Geometric, Poisson, Normal, Exponential and Hyper-geometric distributions.', '["One dimensional random variables, discrete and continuous: definition, moments and their distributions", "Applications to Bernoulli, Binomial, Geometric, Poisson, Normal, Exponential and Hyper-geometric distributions"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 131', 'Inference I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'first', 2, 'Statistical Data: sources, collection, presentation and analysis. Measures of central tendency and dispersion, skewness. Moments and kurtosis. Index numbers and demographic measures.', '["Statistical Data: sources, collection, presentation and analysis", "Measures of central tendency and dispersion, skewness", "Moments and kurtosis", "Index numbers and demographic measures"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 132', 'Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'second', 2, 'Elementary Time Series Analysis. Sampling and Statistical Inference: standard error and sampling distributions of the mean and proportion. Tests of significance for means and proportions. Simple linear regression and correlation.', '["Elementary Time Series Analysis", "Sampling and Statistical Inference: standard error and sampling distributions of the mean and proportion", "Tests of significance for means and proportions", "Simple linear regression and correlation"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 172', 'Statistical Computing I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'second', 2, 'Generation of data using table of random numbers. Presentation and analysis of data. Computations using calculator involving measures of central tendency and dispersion, time series, index numbers, simple linear regression and correlation. Test of significance, one sample only.', '["Generation of data using table of random numbers", "Presentation and analysis of data", "Computations using calculator involving measures of central tendency and dispersion, time series, index numbers, simple linear regression and correlation", "Test of significance, one sample only"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 201', 'Statistics for Social Sciences I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '200 Level', 'first', 2, 'Sources, collection, analysis and presentations of data. Index numbers, elementary analysis of time series, simple linear regression and correlation. Elementary non parametric tests.', '["Sources, collection, analysis and presentations of data", "Index numbers, elementary analysis of time series, simple linear regression and correlation", "Elementary non parametric tests"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 202', 'Statistics for Social Sciences II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '200 Level', 'second', 2, 'Introductory probability. Binomial, Normal and Poisson distributions. Interval estimation and test of significance. Association of Attributes.', '["Introductory probability", "Binomial, Normal and Poisson distributions", "Interval estimation and test of significance", "Association of Attributes"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 203', 'Statistics for Agricultural and Biological Sciences I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '200 Level', 'first', 2, 'Initial steps in planning of biological experiments. Methods of data collection, presentation and analysis. Measures of central tendency and dispersion. Frequency distributions. Elementary probability. Discrete and continuous distributions: Binomial, Poisson, Normal and exponential distributions. Interval estimation.', '["Initial steps in planning of biological experiments", "Methods of data collection, presentation and analysis", "Measures of central tendency and dispersion", "Frequency distributions", "Elementary probability", "Discrete and continuous distributions: Binomial, Poisson, Normal and exponential distributions", "Interval estimation"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 204', 'Statistics for Agricultural and Biological Sciences II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '200 Level', 'second', 2, 'Tests of significance. Student $t$ test and $\chi^2$ test. Two sample test and paired comparison. Regression and correlation. Analysis of variance: one way, two way with no interaction. Latin square analysis. Multiple range tests. Analysis of covariance. Simple analysis of direct assays.', '["Tests of significance", "Student $t$ test and $\\chi^2$ test", "Two sample test and paired comparison", "Regression and correlation", "Analysis of variance: one way, two way with no interaction", "Latin square analysis", "Multiple range tests", "Analysis of covariance", "Simple analysis of direct assays"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 205', 'Statistics for Physical Sciences and Engineering I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '200 Level', 'first', 2, 'Frequency Distributions. Elements of Probability. Discrete probability distributions: Binomial, Poisson, Geometric and Hyper-geometric. Continuous probability distributions: Normal, Student''s $t$, Chi-square $\chi^2$ and $F$. Combinatorial and moment generating functions.', '["Frequency Distributions", "Elements of Probability", "Discrete probability distributions: Binomial, Poisson, Geometric and Hyper-geometric", "Continuous probability distributions: Normal, Student''s $t$, Chi-square $\\chi^2$ and $F$", "Combinatorial and moment generating functions"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 206', 'Statistics for Physical Sciences and Engineering II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '200 Level', 'second', 2, 'Estimation: point and interval. Test of significance. Regression and correlation. Analysis of variance: one-way and two-way with no interaction.', '["Estimation: point and interval", "Test of significance", "Regression and correlation", "Analysis of variance: one-way and two-way with no interaction"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 211', 'Probability III', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '200 Level', 'first', 2, 'Combinatorial analysis. Probability models for the study of random phenomena in finite sample spaces up to and including Bayes Theorem. Probability distribution of Discrete and Continuous two-dimensional random variables. Expectation and Univariate moment generating functions. Truncated distributions.', '["Combinatorial analysis", "Probability models for the study of random phenomena in finite sample spaces up to and including Bayes Theorem", "Probability distribution of Discrete and Continuous two-dimensional random variables", "Expectation and Univariate moment generating functions", "Truncated distributions"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 212', 'Probability IV', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '200 Level', 'second', 2, 'Tchebychev''s inequality. Normal approximation to Binomial distribution. Bivariate, marginal and conditional distributions and their moments. Convolution of two distributions.', '["Tchebychev''s inequality", "Normal approximation to Binomial distribution", "Bivariate, marginal and conditional distributions and their moments", "Convolution of two distributions"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 231', 'Statistical Inference III', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '200 Level', 'first', 3, 'Estimation: point estimation by method of moments, maximum likelihood and least square. Properties of estimators: Unbiasedness, Efficiency, Consistency, definition only. Interval Estimation: Confidence interval for proportions, means, variance and variance ratio. Test of significance: Tests based on normal, $t$, chi-square and $F$ distributions with regard to means, proportions, variance. Tests for independence of attributes and goodness-of-fit.', '["Estimation: point estimation by method of moments, maximum likelihood and least square", "Properties of estimators: Unbiasedness, Efficiency, Consistency, definition only", "Interval Estimation: Confidence interval for proportions, means, variance and variance ratio", "Test of significance: Tests based on normal, $t$, chi-square and $F$ distributions with regard to means, proportions, variance", "Tests for independence of attributes and goodness-of-fit"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 272', 'Statistical Computing II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '200 Level', 'second', 2, 'Use of computer software packages such as Minitab and Excel on probability and inference.', '["Use of computer software packages such as Minitab and Excel on probability and inference"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 311', 'Probability V', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '300 Level', 'first', 3, 'Probability Generating function. Bivariate Normal distribution: conditional and marginal densities, bivariate moment generating functions, characteristic function and inversion formula. Various modes of convergence. Central limit theorem. Elements of measure. Field of sets, fields, measure functions, probability measure and probability space. Introduction to Markov chains: basic concepts, state and parameter space, transition probabilities.', '["Probability Generating function", "Bivariate Normal distribution: conditional and marginal densities, bivariate moment generating functions, characteristic function and inversion formula", "Various modes of convergence", "Central limit theorem", "Elements of measure", "Field of sets, fields, measure functions, probability measure and probability space", "Introduction to Markov chains: basic concepts, state and parameter space, transition probabilities"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 321', 'Distribution Theory', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '300 Level', 'first', 2, 'Bivariate Normal Distribution, the gamma, chi-square, two types of Beta, $F$ and $t$ distributions. Distribution of functions of random variables: sums, products and quotients. Probability integral transformation. Order statistics and their functions.', '["Bivariate Normal Distribution, the gamma, chi-square, two types of Beta, $F$ and $t$ distributions", "Distribution of functions of random variables: sums, products and quotients", "Probability integral transformation", "Order statistics and their functions"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 323', 'Analysis of Variance', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '300 Level', 'first', 3, 'Analysis of one, double and multiple classifications of balanced data in crossed and nested arrangements. Analysis of two and three-way contingency tables for test of independence and interactions. Incomplete block designs. Log linear models. Analysis of covariance in one-way, two-way, three-way and nested classifications.', '["Analysis of one, double and multiple classifications of balanced data in crossed and nested arrangements", "Analysis of two and three-way contingency tables for test of independence and interactions", "Incomplete block designs", "Log linear models", "Analysis of covariance in one-way, two-way, three-way and nested classifications"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 325', 'Biometrics I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '300 Level', 'first', 3, 'Direct Assays: types, nature and examples. Precision of estimates, Fieller''s theorem, dilution assays and design of direct assays. Indirect Assays: the dose response regression, condition of similarity and monotony. Linearizing transformations and non-linear regression. Parallel line assays: unsymmetrical designs, difference in preparations, potency estimation and fiducial limits and validity test. Approximate and exact analyses for missing entries. Symmetry design for parallel line assays. Efficiency, Reliability and Sensitivity.', '["Direct Assays: types, nature and examples", "Precision of estimates, Fieller''s theorem, dilution assays and design of direct assays", "Indirect Assays: the dose response regression, condition of similarity and monotony", "Linearizing transformations and non-linear regression", "Parallel line assays: unsymmetrical designs, difference in preparations, potency estimation and fiducial limits and validity test", "Approximate and exact analyses for missing entries", "Symmetry design for parallel line assays", "Efficiency, Reliability and Sensitivity"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 331', 'Inference IV', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '300 Level', 'first', 3, 'Criteria of Estimation: unbiasedness, consistency, efficiency, sufficiency and minimum variance, with proofs. Rao-Cramer Inequality. Testing of hypothesis: Null and alternative hypothesis, simple, composite hypothesis. Two types of error, critical region, Power size of a test, p-value, Neyman-Pearson Theorem. Most powerful test, and likelihood ratio test.', '["Criteria of Estimation: unbiasedness, consistency, efficiency, sufficiency and minimum variance, with proofs", "Rao-Cramer Inequality", "Testing of hypothesis: Null and alternative hypothesis, simple, composite hypothesis", "Two types of error, critical region, Power size of a test, p-value, Neyman-Pearson Theorem", "Most powerful test, and likelihood ratio test"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 341', 'Sampling Theory and Survey Methods I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '300 Level', 'first', 3, 'Basic sample selection procedures. Estimation of population mean, total and proportions in simple random sampling with and without replacement. Use of auxiliary information: ratio, regression and difference estimators. Stratification: Estimation of mean total population in stratified random sampling. Sample size allocation. Cluster sampling. Two stage Cluster sampling with clusters of equal sizes. Data collection in social investigations. Methods of social investigations. Planning of surveys. Methods of collecting information. Questionnaire design. Response errors, processing analysis and presentation of data.', '["Basic sample selection procedures", "Estimation of population mean, total and proportions in simple random sampling with and without replacement", "Use of auxiliary information: ratio, regression and difference estimators", "Stratification: Estimation of mean total population in stratified random sampling", "Sample size allocation", "Cluster sampling", "Two stage Cluster sampling with clusters of equal sizes", "Data collection in social investigations", "Methods of social investigations", "Planning of surveys", "Methods of collecting information", "Questionnaire design", "Response errors, processing analysis and presentation of data"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 343', 'Laboratory for Sampling and Survey Methods', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '300 Level', 'first', 2, 'Computations involving Stratification. Ratio and regression estimates, cluster and two stage sampling, Field Work.', '["Computations involving Stratification", "Ratio and regression estimates, cluster and two stage sampling, Field Work"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 345', 'Statistical Quality Control', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '300 Level', 'first', 3, 'Concept of quality and meaning of control. Specifications: Control limits and specifications, process spread and specifications. Control charts for variables and attributes: Determination of process capability and standard CuSuM charts. Acceptance sample inspection by attributes: single, double and multiple sampling plans.', '["Concept of quality and meaning of control", "Specifications: Control limits and specifications, process spread and specifications", "Control charts for variables and attributes: Determination of process capability and standard CuSuM charts", "Acceptance sample inspection by attributes: single, double and multiple sampling plans"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 347', 'Laboratory and Field Work for Quality Control I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '300 Level', 'first', 2, 'Practical construction of control charts. Computations involving tolerance limits, simple, multiple and sequential sampling plans. Use of the Poisson approximation to design sampling plans for the producers and consumers risk method. Design and analysis of various rectification schemes.', '["Practical construction of control charts", "Computations involving tolerance limits, simple, multiple and sequential sampling plans", "Use of the Poisson approximation to design sampling plans for the producers and consumers risk method", "Design and analysis of various rectification schemes"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 351', 'Demography', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '300 Level', 'first', 3, 'Sources of demographic data: Census and vital registration. Rates and ratios. Study of mortality. Construction of Life tables. Expectation of life. Measure of fertility and morbidity. Population growth and projection. Migration and the population distribution: interpretation of population parameters from defective data. Stable and quasi stable populations.', '["Sources of demographic data: Census and vital registration", "Rates and ratios", "Study of mortality", "Construction of Life tables", "Expectation of life", "Measure of fertility and morbidity", "Population growth and projection", "Migration and the population distribution: interpretation of population parameters from defective data", "Stable and quasi stable populations"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 353', 'Laboratory and Field Work for Demography', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '300 Level', 'first', 2, 'Computations involving mortality and fertility rates, life tables and population growth.', '["Computations involving mortality and fertility rates, life tables and population growth"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 357', 'Actuarial Statistics I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '300 Level', 'first', 2, 'Effective rate of interest, Normal rate of interest, Force of interest. Relationship between $i$, $i^{(m)}$ and Present Value. Elective and normal rate of Discount. Present value of immediate Annuity, annuity due, increasing and decreasing Annuities, Continuous Annuity. Accumulation of Annuities increasing by step and continuously. Repayment of loan by equated installments: Annuity and Sinking funds. Capital and Interest Element contained in the $t$-th installment. Purchase price of annuities, net of Tax-Loan Schedules.', '["Effective rate of interest, Normal rate of interest, Force of interest", "Relationship between $i$, $i^{(m)}$ and Present Value", "Elective and normal rate of Discount", "Present value of immediate Annuity, annuity due, increasing and decreasing Annuities, Continuous Annuity", "Accumulation of Annuities increasing by step and continuously", "Repayment of loan by equated installments: Annuity and Sinking funds", "Capital and Interest Element contained in the $t$-th installment", "Purchase price of annuities, net of Tax-Loan Schedules"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 361', 'Algebraic Basis for Statistics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '300 Level', 'first', 2, 'Vectors: Norms, scalar and cross products. Vector spaces: Basis and dimension. Matrices: elementary operation with matrices and vectors, rank, determinants, linear equations, orthogonality. Bilinear and quadratic forms, eigensystem. Differentiation with vector and matrices.', '["Vectors: Norms, scalar and cross products", "Vector spaces: Basis and dimension", "Matrices: elementary operation with matrices and vectors, rank, determinants, linear equations, orthogonality", "Bilinear and quadratic forms, eigensystem", "Differentiation with vector and matrices"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 363', 'Operations Research I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '300 Level', 'first', 3, 'The Nature of Operations Research: History, meaning and models. Classical methods of optimization: maxima and minima, Lagrange''s Multipliers, Convex set and functions. Linear Programming: formulation and Analysis using graphs. Simplex and revised simplex methods. Duality Theory and Applications. Sensitivity Analysis in Linear Programming.', '["The Nature of Operations Research: History, meaning and models", "Classical methods of optimization: maxima and minima, Lagrange''s Multipliers, Convex set and functions", "Linear Programming: formulation and Analysis using graphs", "Simplex and revised simplex methods", "Duality Theory and Applications", "Sensitivity Analysis in Linear Programming"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 365', 'Laboratory for Operations Research I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '300 Level', 'first', 2, 'Problem formulation involving linear programming applications. Computations involving simplex and revised simplex algorithms, graphs.', '["Problem formulation involving linear programming applications", "Computations involving simplex and revised simplex algorithms, graphs"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 371', 'Statistical Computing III', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '300 Level', 'first', 2, 'Use of computer packages such as GENSTAT and SPSS and other current packages on topics in Inference IV, ANOVA, Operations Research, Regression and many other applicable areas.', '["Use of computer packages such as GENSTAT and SPSS and other current packages on topics in Inference IV, ANOVA, Operations Research, Regression and many other applicable areas"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 382', 'Practical on Industrial Training', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '300 Level', 'second', 3, 'Practical work engaged in during the Industrial Training.', '["Practical work engaged in during the Industrial Training"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 384', 'Report on Industrial Training', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '300 Level', 'second', 12, 'Report to be presented after the Industrial Training.', '["Report to be presented after the Industrial Training"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 411', 'Probability VII', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'first', 3, 'Probability spaces, measures and distributions. Product spaces: product of measurable spaces, product probabilities. Random variables as measurable functions. Independence and expectations of product random variables. Convergence of random variables: Weak convergence, convergence almost everywhere, convergence in $p$-th mean. Central Limit Theorem. Characteristic function and Laplace transforms. Inversion formula.', '["Probability spaces, measures and distributions", "Product spaces: product of measurable spaces, product probabilities", "Random variables as measurable functions", "Independence and expectations of product random variables", "Convergence of random variables: Weak convergence, convergence almost everywhere, convergence in $p$-th mean", "Central Limit Theorem", "Characteristic function and Laplace transforms", "Inversion formula"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 413', 'Stochastic Processes I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'first', 2, 'Random walk: simple and general random walk with absorbing and reflecting barriers. Markovian processes with finite chains. Branching processes, Poisson process, relevant applications.', '["Random walk: simple and general random walk with absorbing and reflecting barriers", "Markovian processes with finite chains", "Branching processes, Poisson process, relevant applications"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 414', 'Stochastic Processes II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'second', 2, 'Birth and Death Processes. Queuing Processes: M/M/1, M/M/S, M/C and G/M/1 Queues and their waiting time distributions. Diffusion Process. Relevant applications.', '["Birth and Death Processes", "Queuing Processes: M/M/1, M/M/S, M/C and G/M/1 Queues and their waiting time distributions", "Diffusion Process", "Relevant applications"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 415', 'Time Series I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'first', 2, 'Components of Time Series, measurement of trend, the seasonal index, the cyclical component and random fluctuations, serial correlation, Correlogram.', '["Components of Time Series, measurement of trend, the seasonal index, the cyclical component and random fluctuations, serial correlation, Correlogram"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 416', 'Time Series II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'second', 2, 'Stationary Time Series: Second order Stationarity, the autocorrelation function. Autoregressive process, Moving Average Processes of mixed models. Integrated Models. Estimation of the Parameters, Forecasting and Spectral density.', '["Stationary Time Series: Second order Stationarity, the autocorrelation function", "Autoregressive process, Moving Average Processes of mixed models", "Integrated Models", "Estimation of the Parameters, Forecasting and Spectral density"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 421', 'Design and Analysis of Experiment I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'first', 2, 'Meaning, Need, Purpose and Basic Principles of Experimental Design. Efficient design: Randomization, replication and blocking, local control. Basic designs: Completely randomized design (CRD), Randomized complete block design (RCBD), Latin square design. Relative efficiency, missing values. Multiple comparisons. Departures from underlying assumptions and examples from agriculture, biology and industry.', '["Meaning, Need, Purpose and Basic Principles of Experimental Design", "Efficient design: Randomization, replication and blocking, local control", "Basic designs: Completely randomized design (CRD), Randomized complete block design (RCBD), Latin square design", "Relative efficiency, missing values", "Multiple comparisons", "Departures from underlying assumptions and examples from agriculture, biology and industry"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 422', 'Design and Analysis of Experiment II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'second', 2, 'BIB designs, and factorial experiments. Split-plot design. Expected mean square (EMS) rules, $2^n$ factorial designs: Yates algorithm, confounding, fractional replication. Applications with real life data. Introduction to response surface methodology.', '["BIB designs, and factorial experiments", "Split-plot design", "Expected mean square (EMS) rules, $2^n$ factorial designs: Yates algorithm, confounding, fractional replication", "Applications with real life data", "Introduction to response surface methodology"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 423', 'Regression Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'first', 3, 'Simple linear and multiple regression. Inference on regression parameters. Polynomial regression. Examination of residuals, use of dummy variable. Reparametrization of non-linear models. Partial, total and multiple correlation ratio. Generalized least squares. Prediction from regression. Multicollinearity, autocorrelation and Heteroscedasticity: Durbin-Watson test, Outliers, Selection of the best regression equation. Simple treatment of logistic regression.', '["Simple linear and multiple regression", "Inference on regression parameters", "Polynomial regression", "Examination of residuals, use of dummy variable", "Reparametrization of non-linear models", "Partial, total and multiple correlation ratio", "Generalized least squares", "Prediction from regression", "Multicollinearity, autocorrelation and Heteroscedasticity: Durbin-Watson test, Outliers, Selection of the best regression equation", "Simple treatment of logistic regression"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 425', 'Biometrics II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'first', 2, 'Slope ratio assays: the power dose metameter, multiple regression equation. Analysis of variance and validity tests. Symmetrical $(2K+1)$ point design. Comparison of assay techniques.', '["Slope ratio assays: the power dose metameter, multiple regression equation", "Analysis of variance and validity tests", "Symmetrical $(2K+1)$ point design", "Comparison of assay techniques"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 426', 'Biometrics III', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'second', 2, 'Multiple assays: economy of multiple assays, multiple slope ratio assays and Design of multiple assays. Distribution of responses between preparations. Composite responses, the discriminant problem, examples of an assay using a Discriminant function; discriminants and concomitants; the economies of Discriminant analysis.', '["Multiple assays: economy of multiple assays, multiple slope ratio assays and Design of multiple assays", "Distribution of responses between preparations", "Composite responses, the discriminant problem, examples of an assay using a Discriminant function; discriminants and concomitants; the economies of Discriminant analysis"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 431', 'Bayesian Inference I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'first', 2, 'Bayes'' theorem. Posterior distributions. Point estimation with the loss functions. Squared error loss, absolute error loss and zero one loss. Interval estimation, shortest, highest posterior density (HPD), equal tail and one tail interval, prediction of a future observation. Choice of prior: natural conjugate family of priors (NCP) and non-informative priors (NIP). Application to some standard one and two-parameter problems.', '["Bayes'' theorem", "Posterior distributions", "Point estimation with the loss functions", "Squared error loss, absolute error loss and zero one loss", "Interval estimation, shortest, highest posterior density (HPD), equal tail and one tail interval, prediction of a future observation", "Choice of prior: natural conjugate family of priors (NCP) and non-informative priors (NIP)", "Application to some standard one and two-parameter problems"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 432', 'Bayesian Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'second', 2, 'Comparison of the means and variances of two normal and two Poisson distributions. Linear regression: joint and marginal posterior distributions of regression parameters for normally distributed regressor variables. Tests of hypothesis: Jeffrey''s methods and decision theoretic approach. Applications.', '["Comparison of the means and variances of two normal and two Poisson distributions", "Linear regression: joint and marginal posterior distributions of regression parameters for normally distributed regressor variables", "Tests of hypothesis: Jeffrey''s methods and decision theoretic approach", "Applications"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 433', 'Multivariate Analysis I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'first', 2, 'The multivariate normal distribution: definition, generating function, conditional distribution of the estimates. The Hotelling''s distribution, Wishart distribution. Inference about mean vectors: one sample and two sample cases. Tests of independence.', '["The multivariate normal distribution: definition, generating function, conditional distribution of the estimates", "The Hotelling''s distribution, Wishart distribution", "Inference about mean vectors: one sample and two sample cases", "Tests of independence"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 434', 'Multivariate Analysis II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'second', 2, 'Classification: the linear discriminant function for two groups, errors of Misclassification and estimation of misclassification probabilities. Principal components: meaning, computation and interpretation; sampling properties. Factor analysis: model for factor structure, estimation of factor loadings, factor rotation applications.', '["Classification: the linear discriminant function for two groups, errors of Misclassification and estimation of misclassification probabilities", "Principal components: meaning, computation and interpretation; sampling properties", "Factor analysis: model for factor structure, estimation of factor loadings, factor rotation applications"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 435', 'Non-Parametric Methods I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'first', 2, 'Nonparametric versus parametric inference. Distribution-free Statistics. Order Statistics.', '["Nonparametric versus parametric inference", "Distribution-free Statistics", "Order Statistics"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 436', 'Non-Parametric Methods II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'second', 2, 'Rank estimates of location in one and two sample problems. Rank test applied to $C > 2$ samples: Kruskal-Wallis and Friedman tests. Rank test in simple linear regression and correlation. Sample cases. Tests of independence.', '["Rank estimates of location in one and two sample problems", "Rank test applied to $C > 2$ samples: Kruskal-Wallis and Friedman tests", "Rank test in simple linear regression and correlation", "Sample cases", "Tests of independence"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 437', 'Psychometrics I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'first', 2, 'Foundations of mental measurement theory: measurements in psychology and education, construction of true scores: the classical test theory model: basic equations for test of fixed length and for homogeneous test for variable length. Composite test, Factors affecting measurement precision, estimation and prediction. Estimate of parameters of the classical model.', '["Foundations of mental measurement theory: measurements in psychology and education, construction of true scores: the classical test theory model: basic equations for test of fixed length and for homogeneous test for variable length", "Composite test, Factors affecting measurement precision, estimation and prediction", "Estimate of parameters of the classical model"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 438', 'Psychometrics II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'second', 2, 'Other weak true-score models. Some test theory for imperfectly parallel measurements, types of reliability coefficients and their estimation. Some test theory for equivalent measurement, item sample in test theory and in research design. Applications.', '["Other weak true-score models", "Some test theory for imperfectly parallel measurements, types of reliability coefficients and their estimation", "Some test theory for equivalent measurement, item sample in test theory and in research design", "Applications"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 441', 'Sampling Theory and Survey Methods II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'first', 2, 'Unequal probability sampling; probability proportional to size with replacement and probability proportional to size-systematic selections, with cluster of unequal size. Multistage sampling. Estimation totals, ratio. Double sampling for ratio and regression estimation. Gains in precision due to stratification, post stratification Domain estimation. Practical examples.', '["Unequal probability sampling; probability proportional to size with replacement and probability proportional to size-systematic selections, with cluster of unequal size", "Multistage sampling", "Estimation totals, ratio", "Double sampling for ratio and regression estimation", "Gains in precision due to stratification, post stratification Domain estimation", "Practical examples"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 451', 'Actuarial Statistics II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'first', 2, 'Investment and appraisal techniques; analysis of experiments, data and derivation of exposed to risk formulae. Graduation methods and their application to curve fitting. Construction of mortality, sickness, multiple decrements and similar tables with application to life insurance. National social security and pension schemes. Stochastic interest rate models. Independent annual interest rates. Mean and variance of $S_n$ and $A_n$ and simple problems associated with these.', '["Investment and appraisal techniques; analysis of experiments, data and derivation of exposed to risk formulae", "Graduation methods and their application to curve fitting", "Construction of mortality, sickness, multiple decrements and similar tables with application to life insurance", "National social security and pension schemes", "Stochastic interest rate models", "Independent annual interest rates", "Mean and variance of $S_n$ and $A_n$ and simple problems associated with these"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 452', 'Medical Statistics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'second', 2, 'Scope and nature of medical statistics, epidemiology methods; relative risks and odds ratios, adjustment of data with and without use of multivariate models, cohort studies, life tables, competing risks survival analysis. Sequential methods in clinical trial. Stochastic models in epidemiology and other areas.', '["Scope and nature of medical statistics, epidemiology methods; relative risks and odds ratios, adjustment of data with and without use of multivariate models, cohort studies, life tables, competing risks survival analysis", "Sequential methods in clinical trial", "Stochastic models in epidemiology and other areas"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 453', 'Health Statistics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'first', 2, 'Scope and types of health statistics, classification of diseases, injuries and causes of death. Sources and method of collecting health statistics; census, sample surveys, vital registration and administrative statistics. Health indicators: types, uses and problems. Health planning and financing. Health information system. Operations research in the health services.', '["Scope and types of health statistics, classification of diseases, injuries and causes of death", "Sources and method of collecting health statistics; census, sample surveys, vital registration and administrative statistics", "Health indicators: types, uses and problems", "Health planning and financing", "Health information system", "Operations research in the health services"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 454', 'Energy Statistics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'second', 2, 'Energy source: renewable and non-renewable. Nature, scope and uses of Energy Statistics. Concepts, definition and units of measurement in use in Energy Statistics. Energy production and consumption survey. Data requirements and the procedure for developing an energy database. Constructing an energy balance sheet with Nigeria as a case study. Modelling energy supply and demand.', '["Energy source: renewable and non-renewable", "Nature, scope and uses of Energy Statistics", "Concepts, definition and units of measurement in use in Energy Statistics", "Energy production and consumption survey", "Data requirements and the procedure for developing an energy database", "Constructing an energy balance sheet with Nigeria as a case study", "Modelling energy supply and demand"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 455', 'Environmental Statistics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'first', 2, 'Scope, nature and sources of environmental Statistics. Assessment of environmental quality and measurement of air and water pollution. Sampling method in natural and applied sciences. Environmental impact assessment. Requirement for environmental reporting system. Characteristics and uses of the United Nations framework for the development of environmental statistics. Capacity building for environmental reporting system.', '["Scope, nature and sources of environmental Statistics", "Assessment of environmental quality and measurement of air and water pollution", "Sampling method in natural and applied sciences", "Environmental impact assessment", "Requirement for environmental reporting system", "Characteristics and uses of the United Nations framework for the development of environmental statistics", "Capacity building for environmental reporting system"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 457', 'Educational Statistics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'first', 2, 'Source, nature and uses of educational Statistics. Sources and methods of collecting educational statistics. Educational indicators. Design of educational information systems, educational models and performance of flows, including manpower, evaluation. Multivariate methods in educational analysis, Operations research in educational management.', '["Source, nature and uses of educational Statistics", "Sources and methods of collecting educational statistics", "Educational indicators", "Design of educational information systems, educational models and performance of flows, including manpower, evaluation", "Multivariate methods in educational analysis, Operations research in educational management"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 461', 'Operations Research II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'first', 2, 'Game theory: two persons; zero sum games, saddle point, dominance and strategies. Mathematical programming: non-linear programming, integer programming, dynamic programming. Theory of reliability: reliability function, active and passive reliability; reliability of systems in series, in parallel, and voting. Hazard rate. Mean time to failure.', '["Game theory: two persons; zero sum games, saddle point, dominance and strategies", "Mathematical programming: non-linear programming, integer programming, dynamic programming", "Theory of reliability: reliability function, active and passive reliability; reliability of systems in series, in parallel, and voting", "Hazard rate", "Mean time to failure"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 462', 'Operations Research III', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'second', 2, 'Optimization. Network analysis: network flows, transportation problem. Assignment problem, maximal flow problem, critical path method (CPM) and Project Evaluation and Review Technique (PERT).', '["Optimization", "Network analysis: network flows, transportation problem", "Assignment problem, maximal flow problem, critical path method (CPM) and Project Evaluation and Review Technique (PERT)"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 463', 'Decision Theory I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'first', 2, 'Formulation of decision-theoretic problems, comparison between game theory and decision theory. Risk, utility, loss and decision function.', '["Formulation of decision-theoretic problems, comparison between game theory and decision theory", "Risk, utility, loss and decision function"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 464', 'Decision Theory II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'second', 2, 'Admissibility and completeness. Minimax and Bayes solution, Invariant statistical problems. Applications.', '["Admissibility and completeness", "Minimax and Bayes solution, Invariant statistical problems", "Applications"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 466', 'Laboratory for Operations Research II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'second', 2, 'Exercises on problem formulation in applications of Operations Research. Computations in mathematical programming, dynamic programming, integer programming, non-linear programming, network analysis and game theory.', '["Exercises on problem formulation in applications of Operations Research", "Computations in mathematical programming, dynamic programming, integer programming, non-linear programming, network analysis and game theory"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 492', 'Project', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'second', 6, 'Each final year student is expected to produce an acceptable first hand study of an approved topic under staff supervision. The project should be based on some of the theories and techniques covered in the courses.', '["Each final year student is expected to produce an acceptable first hand study of an approved topic under staff supervision", "The project should be based on some of the theories and techniques covered in the courses"]'::jsonb, 'Department of Statistics handbook'),
  ('MTH 111', 'Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'first', 3, 'Elementary Set theory, subsets, union, intersection, complements. Venn diagrams, Real numbers, integers, rational and irrational numbers, mathematical induction, real sequences and series, theory of quadratic equations, binomial theorem. Circular measure, trigonometric functions of angles of any magnitude, addition and factor formulae. Complex numbers, algebra of complex numbers, the Argand Diagram, De Moivre''s theorem, $n$th roots of unity.', '["Elementary Set theory, subsets, union, intersection, complements", "Venn diagrams, Real numbers, integers, rational and irrational numbers, mathematical induction, real sequences and series, theory of quadratic equations, binomial theorem", "Circular measure, trigonometric functions of angles of any magnitude, addition and factor formulae", "Complex numbers, algebra of complex numbers, the Argand Diagram, De Moivre''s theorem, $n$th roots of unity"]'::jsonb, 'Department of Statistics undergraduate course module'),
  ('MTH 121', 'Elementary Mathematics II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'first', 3, 'Functions of a real variable, graphs, limits and continuity. The derivative as limit of rate of change. Techniques of differentiation. Curve sketching, integration as an inverse of differentiation. Methods of integration, definite integrals. Application of integration to areas and volumes.', '["Functions of a real variable, graphs, limits and continuity", "The derivative as limit of rate of change", "Techniques of differentiation", "Curve sketching, integration as an inverse of differentiation", "Methods of integration, definite integrals", "Application of integration to areas and volumes"]'::jsonb, 'Department of Statistics undergraduate course module'),
  ('COS 101', 'Introduction to Computer Science I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'first', 2, 'Concepts of hardware and software; basic subsystems of a digital computer; characteristics of a digital computer; devices/media; types/classes of computer emphasising the PC; history of computers and their generations. Problem-solving: algorithm, flowchart, pseudocode, program/data, running a program. Programming: introduction to Java/BASIC programming language syntax and programming. Booting and shutdown; types of operating system; user interface; managing information, computer malware (virus, etc); computer network; internet and web usage, e-mail, instant messaging, etc. Office applications; use of a statistical package and a database management system.', '["Concepts of hardware and software","basic subsystems of a digital computer","characteristics of a digital computer","devices/media","types/classes of computer emphasising the PC","history of computers and their generations","Problem-solving: algorithm, flowchart, pseudocode, program/data, running a program","Programming: introduction to Java/BASIC programming language syntax and programming","Booting and shutdown","types of operating system","user interface","managing information, computer malware (virus, etc)","computer network","internet and web usage, e-mail, instant messaging, etc","Office applications","use of a statistical package and a database management system"]'::jsonb, 'Department of Computer Science course outline'),
  ('GSP 101', 'The Use of English I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'first', 2, 'Man, Society and Language - The Nature, Characteristics and Functions of Language, Human Communication & Language, The English Language and the Nigerian society, World English, Levels and Varieties of English — formal, informal, standard, etc., English in Literature and the Media.

Vocabulary of English - Types, Method of Vocabulary Development, Synonyms, Antonyms, Homonyms, Acronyms, Paronyms, Affixation and other morphological processes, English Language Register, diatypes and dialects.

Listening skill - The listening skill discussed as a receptive and reciprocal activity, Nature, Types, Purposes and Factors that affect Listening, Strategies and Aids for Effective Listening.

Reading Skill - The concept of reading as a linguistic organization and a vehicle of communication. Reading Problems, Levels of Reading, Types of Reading, Causes and Remedies of Reading Failures, Reading Techniques & Strategies (Scanning, Skimming, Phrase reading, Intensive & Extensive reading, Exploiting the topic sentence for main ideas), Reading for details, Reading for evaluation and inference, Reading with questions - SQ3R, PR3, Methods for understanding difficult words in a reading text, Literature reading for study, analysis and comment.

Speaking & Communication Skills - Nature, Process & Development, Principles of Public Speech Making and Social Interaction, The Speech Sounds of English and their Articulation, Phonetic Transcription and Practical Speech Work.

Study Techniques - Choosing study centers and discussion groups, Note-taking during lectures, and from audio-visual equipment, Note-making techniques during private reading and literature search, Summary & Transcoding Techniques, Retrieving information from notes, The dictionary as a study guide.

Basic Research Methods & Term Paper Writing - Research – meaning & nature, Types & Methodology; Data in the Research Process, The Research Report, Process and Techniques, Documentation in Research Reports: Process, Types and Methods, Abbreviations in Research Reports, The term paper as a miniature research report, Practical term paper writing.

Course Evaluation & Grading - Students must attend at least 75% of the lectures to qualify for examination in the course.', '["Man, Society and Language - The Nature, Characteristics and Functions of Language, Human Communication & Language, World English, Levels and Varieties of English", "Vocabulary of English - Types, Method of Vocabulary Development, Synonyms, Antonyms, Homonyms, Acronyms, Paronyms, Affixation and other morphological processes", "Listening skill - Nature, Types, Purposes and Factors that affect Listening, Strategies and Aids for Effective Listening", "Reading Skill - Reading Problems, Levels and Types of Reading, Causes and Remedies of Reading Failures, Reading Techniques & Strategies, Reading for evaluation and inference", "Speaking & Communication Skills - Principles of Public Speech Making and Social Interaction, Phonetic Transcription and Practical Speech Work", "Study Techniques - Note-taking, Note-making, Summary & Transcoding Techniques", "Basic Research Methods & Term Paper Writing - The Research Report, Documentation, Abbreviations, practical term paper writing"]'::jsonb, 'Department of Mechanical Engineering handbook'),
  ('GSP 111', 'The Use of Library', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'first', 2, 'Overview of Library: concepts, history, types and functions. Uses in academic libraries; organization of university library and library users. Library processes and procedures. Acquisition process, Cataloging and classification, LC Scheme, in-House Scheme, DDC. Serials process and circulation processes. Access tools in Library resources: Library catalogues, Indexes, Abstracts, Current contents information in the library. Reference sources: types of reference sources and services. Web resources and online resources. Overview of Databases, Online search strategies for information retrieval. Referencing and citation styles for information reporting. Concept of plagiarism. Learning skills and research skills, ICT skillsets: types of learning and information policies.', '["Overview of Library: concepts, history, types and functions. Uses in academic libraries; organization of university library and library users", "Library processes and procedures. Acquisition process, Cataloging and classification, LC Scheme, in-House Scheme, DDC. Serials process and circulation processes", "Access tools in Library resources: Library catalogues, Indexes, Abstracts, Current contents information", "Reference sources: types of reference sources and services. Web resources and online resources", "Overview of Databases, Online search strategies for information retrieval. Referencing and citation styles for information reporting. Concept of plagiarism", "Learning skills and research skills, ICT skillsets: types of learning and information policies"]'::jsonb, 'Department of Mechanical Engineering handbook'),
  ('PHY 123', 'General Physics for Physical Sciences', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'first', 2, 'Elective.', '[]'::jsonb, 'Department of Statistics undergraduate course module'),
  ('PHY 191', 'Practical Physics I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'first', 2, 'Elective. Selected experiments from the 100-Level courses in Physics for service courses.', '["Selected experiments from the 100-Level courses in Physics for service courses"]'::jsonb, 'Department of Statistics undergraduate course module'),
  ('CHM 101', 'Basic Principles of Inorganic Chemistry', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'first', 2, 'Elective. Stoichiometry and Atomic Structure: Stoichiometry and mole concept. Introduction to atomic structure, development of electronic configuration of the elements, and valency theories. Periodic Table and Groups: The periodic classification of elements. Brief group study of representative elements, with emphasis on similarities and differences based on periodic position. Nuclear Chemistry: Radioactivity and its practical applications.', '["Stoichiometry and Atomic Structure: Stoichiometry and mole concept. Introduction to atomic structure, development of electronic configuration of the elements, and valency theories", "Periodic Table and Groups: The periodic classification of elements. Brief group study of representative elements, with emphasis on similarities and differences based on periodic position", "Nuclear Chemistry: Radioactivity and its practical applications"]'::jsonb, 'Department of Statistics undergraduate course module'),
  ('CHM 171', 'Basic Practical Chemistry', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'first', 2, 'Elective. Laboratory Operations: Theory and practice of simple volumetric and quantitative analysis, simple organic preparations, functional group reactions, and physical chemistry determinations.', '["Laboratory Operations: Theory and practice of simple volumetric and quantitative analysis, simple organic preparations, functional group reactions, and physical chemistry determinations"]'::jsonb, 'Department of Statistics undergraduate course module'),
  ('ECO 101', 'Principles of Economics I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'first', 2, 'Elective.', '[]'::jsonb, 'Department of Statistics undergraduate course module'),
  ('BIO 151', 'General Biology', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'first', 3, 'Elective.', '[]'::jsonb, 'Department of Statistics undergraduate course module'),
  ('AGR 201', 'Introduction to Agriculture', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'first', 2, 'Elective.', '[]'::jsonb, 'Department of Statistics undergraduate course module'),
  ('GLG 103', 'Basic and Applied Geology for Environmental, Physical and Social Sciences', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'first', 3, 'Elective. The earth and the solar system; internal structures and physics of the earth; important minerals and major rock types; geologic time-scale and geochronology; elements of earth history; relationship between geomorphic and structural features; weathering and erosion, gullying, landslide, floods, desert advance, and environmental pollution, and their control; outlines of the geology and mineral resources of Nigeria.', '["The earth and the solar system", "Internal structures and physics of the earth", "Important minerals and major rock types", "Geologic time-scale and geochronology", "Elements of earth history", "Relationship between geomorphic and structural features", "Weathering and erosion, gullying, landslide, floods, desert advance, and environmental pollution, and their control", "Outlines of the geology and mineral resources of Nigeria"]'::jsonb, 'Department of Statistics undergraduate course module'),
  ('MTH 122', 'Elementary Mathematics III', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'second', 3, 'Geometric representation of vectors in 1-3 dimensions, Components, direction cosines. Addition of vectors and multiplication of vectors by a scalar, linear independence. Scalar and vector products of two vectors. Differentiation and integration of vectors with respect to a scalar variable. Two-dimensional coordinate geometry. Straight lines, circles, parabolas, ellipses, hyperbolas. Tangents and normals. Kinematics of a particle. Components of velocity and acceleration of a particle moving in a plane. Force and momentum. Newton''s laws of motion; motion under gravity, projectile motion, resisted vertical motion of a particle, elastic string, motion of a simple pendulum, impulse and impact of momentum. Impact of two smooth elastic spheres. Direct and oblique impacts.', '["Geometric representation of vectors in 1-3 dimensions, Components, direction cosines", "Addition of vectors and multiplication of vectors by a scalar, linear independence", "Scalar and vector products of two vectors", "Differentiation and integration of vectors with respect to a scalar variable", "Two-dimensional coordinate geometry", "Straight lines, circles, parabolas, ellipses, hyperbolas", "Tangents and normals", "Kinematics of a particle", "Components of velocity and acceleration of a particle moving in a plane", "Force and momentum", "Newton''s laws of motion", "Motion under gravity, projectile motion, resisted vertical motion of a particle, elastic string, motion of a simple pendulum, impulse and impact of momentum", "Impact of two smooth elastic spheres", "Direct and oblique impacts"]'::jsonb, 'Department of Statistics undergraduate course module'),
  ('GSP 102', 'The Use of English II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'second', 2, 'Part A: Basic Grammar: Introduction. The concept of grammar and its place in language teaching and learning. Parts of speech and their functions (treated in detail). Closed and open class items in parts of speech, Nominalization, Grammatical Structures: the phrase, the clause and the sentence. Elementary Clause Analysis, Sentence Types, Elements and Patterns. Agreement (Grammatical agreement, Notional agreement, Proximity agreement) Agreement with the correlatives. Direct and Reported Speech, Error typology identification and correction.

Part B: Varieties of writing. Introduction (The Meaning, Nature and Purpose of Writing, Writing Types or Genres and their Characteristics). The paragraph as the basic unit of an essay (Types, Development of the Paragraph, Methods of Paragraph Development, The thesis statement). Point of view and style in writing. Qualities of a good piece of writing: Form, Diction and Content in writing. The Mechanics of Writing: punctuation, spelling and capitalization.

Part C: Writing Genres - Planning and choosing your theme. Deciding your genre. Choosing and developing your plot. Point of view, setting and characterization. Using the language that works. Essay Writing — Narration, Description, Exposition and Argumentation. Technical Writing: Letter Writing, Memorandum Writing, Speech Writing, Agenda and Minutes, own story for practice, Computer-linked writing, types, style, language, and process.', '["Part A: Basic Grammar - The concept of grammar, Parts of speech, Grammatical Structures, Sentence Types, Agreement, Direct and Reported Speech, Error typology", "Part B: Varieties of writing - Meaning, Nature and Purpose of Writing, the paragraph as the basic unit of an essay, the thesis statement, Qualities of a good piece of writing, Mechanics of Writing", "Part C: Writing Genres - Planning and choosing your theme, plot, point of view, setting and characterization", "Essay Writing - Narration, Description, Exposition and Argumentation", "Technical Writing - Letter Writing, Memorandum Writing, Speech Writing, Agenda and Minutes"]'::jsonb, 'Department of Mechanical Engineering handbook'),
  ('MTH 132', 'Elementary Mechanics I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'second', 3, 'Elective. Vectors: Algebra of vectors; coplanar forces; their resolution into components, equilibrium conditions, moments and couples, parallel forces; friction; centroids and centres of gravity of particles and rigid bodies; equivalence of sets of coplanar forces. Kinematics and rectilinear motion of a particle, vertical motion under gravity, projection, relative motion. Dynamics of a particle. Newton''s laws of motion; motion of connected particles.', '["Vectors: Algebra of vectors", "Coplanar forces", "Their resolution into components, equilibrium conditions, moments and couples, parallel forces", "Friction", "Centroids and centres of gravity of particles and rigid bodies", "Equivalence of sets of coplanar forces", "Kinematics and rectilinear motion of a particle, vertical motion under gravity, projection, relative motion", "Dynamics of a particle", "Newton''s laws of motion", "Motion of connected particles"]'::jsonb, 'Department of Statistics undergraduate course module'),
  ('PHY 134', 'General Physics for Physical Sciences II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'second', 2, 'Elective.', '[]'::jsonb, 'Department of Statistics undergraduate course module'),
  ('PHY 154', 'General Physics for Physical Sciences III', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'second', 2, 'Elective.', '[]'::jsonb, 'Department of Statistics undergraduate course module'),
  ('CHM 112', 'Basic Principles of Physical Chemistry', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'second', 2, 'Elective. Gas Laws and Kinetic Theory: Kinetic theory of gases, elementary derivation and deduction of gas laws, molecular speeds, deviations from ideal behaviour, van der Waals modification, and gas liquefaction. Phase Equilibrium and Solutions: Phase transitions and phase equilibria in one-component systems. Ideal solutions, Raoult''s law, Henry''s law, real solutions, and colligative properties -- vapour pressure lowering, boiling point elevation, freezing point lowering, osmotic pressure. Thermodynamics and Kinetics: Aspects of the first law of thermodynamics, thermochemistry, entropy, free energy, and spontaneous changes. Ionic equilibria, acids, bases, indicators, and buffers. Elementary chemical kinetics, factors affecting reaction rates, rate laws, order and molecularity, zero and first order reactions, Arrhenius equation, and collision and transition state theories.', '["Gas Laws and Kinetic Theory: Kinetic theory of gases, elementary derivation and deduction of gas laws, molecular speeds, deviations from ideal behaviour, van der Waals modification, and gas liquefaction", "Phase Equilibrium and Solutions: Phase transitions and phase equilibria in one-component systems. Ideal solutions, Raoult''s law, Henry''s law, real solutions, and colligative properties -- vapour pressure lowering, boiling point elevation, freezing point lowering, osmotic pressure", "Thermodynamics and Kinetics: Aspects of the first law of thermodynamics, thermochemistry, entropy, free energy, and spontaneous changes. Ionic equilibria, acids, bases, indicators, and buffers. Elementary chemical kinetics, factors affecting reaction rates, rate laws, order and molecularity, zero and first order reactions, Arrhenius equation, and collision and transition state theories"]'::jsonb, 'Department of Statistics undergraduate course module'),
  ('CHM 122', 'Basic Principles of Organic Chemistry', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '100 Level', 'second', 2, 'Elective. Structure and Classification: Historical survey of organic chemistry, IUPAC nomenclature, classification of organic compounds, homologous series, elemental analysis, molecular formulas, and structural isomerism. Bonding and Reactivity: Isolation and purification methods, functional group concepts, resonance, and aromaticity. Electronic theory in organic chemistry. Functional Groups: Brief study of saturated and unsaturated hydrocarbons, cyclic hydrocarbons, alcohols, alkyl halides, ethers, aldehydes, ketones, carboxylic acids, amines, and aromatic compounds. Comparison of phenols and aryl halides. Stereochemistry and Lipids: Introduction to oils, fats, and stereoisomerism.', '["Structure and Classification: Historical survey of organic chemistry, IUPAC nomenclature, classification of organic compounds, homologous series, elemental analysis, molecular formulas, and structural isomerism", "Bonding and Reactivity: Isolation and purification methods, functional group concepts, resonance, and aromaticity. Electronic theory in organic chemistry", "Functional Groups: Brief study of saturated and unsaturated hydrocarbons, cyclic hydrocarbons, alcohols, alkyl halides, ethers, aldehydes, ketones, carboxylic acids, amines, and aromatic compounds. Comparison of phenols and aryl halides", "Stereochemistry and Lipids: Introduction to oils, fats, and stereoisomerism"]'::jsonb, 'Department of Statistics undergraduate course module'),
