  ('COS 201', 'Computer Programming I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '200 Level', 'first', 2, 'Printed in this table as "Computer Programming 11"; every other appearance of COS 201 in this document titles it Computer Programming I, used here.', '[]'::jsonb, 'Faculty of Physical Sciences course catalogue (2014/2015)'),
  ('MTH 215', 'Linear Algebra I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '200 Level', 'first', 2, 'System of linear equations. Matrices and algebra of matrices. Vector spaces over the real field. Subspaces, linear independence, bases and dimensions. Gram-Schmidt orthogonalization procedure. Linear transformations: range, null space and rank. Singular and non-singular transformations.', '["System of linear equations", "Matrices and algebra of matrices", "Vector spaces over the real field", "Subspaces, linear independence, bases and dimensions", "Gram-Schmidt orthogonalization procedure", "Linear transformations: range, null space and rank", "Singular and non-singular transformations"]'::jsonb, 'Department of Statistics undergraduate course module'),
