  ('MTH 224', 'Introduction to Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '200 Level', 'second', 3, 'Elective. Solution of algebraic and transcendental equations. Curve fitting, error analysis. Interpolation, approximation, zeros of non-linear equations of one variable. Systems of linear equations. Numerical differentiation and integration. Numerical solution of initial-value problems for ordinary differential equations.', '["Solution of algebraic and transcendental equations", "Curve fitting, error analysis", "Interpolation, approximation, zeros of non-linear equations of one variable", "Systems of linear equations", "Numerical differentiation and integration", "Numerical solution of initial-value problems for ordinary differential equations"]'::jsonb, 'Department of Statistics undergraduate course module'),
  ('MTH 242', 'Mathematical Methods I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '200 Level', 'second', 3, 'Elective. Real-valued functions of a real variable. Review of differentiation and integration and their applications. Mean-value theorem. Taylor series. Real-valued functions of two or three variables. Partial derivatives. Chain-rule, extrema, Lagrange''s multipliers, increments, differentials and linear approximations. Evaluation of line-integrals. Multiple integrals.', '["Real-valued functions of a real variable", "Review of differentiation and integration and their applications", "Mean-value theorem", "Taylor series", "Real-valued functions of two or three variables", "Partial derivatives", "Chain-rule, extrema, Lagrange''s multipliers, increments, differentials and linear approximations", "Evaluation of line-integrals", "Multiple integrals"]'::jsonb, 'Department of Statistics undergraduate course module'),
  ('ECO 282', 'Structure of Nigerian Economy II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '200 Level', 'second', 2, 'Elective.', '[]'::jsonb, 'Department of Statistics undergraduate course module'),
