  ('COS 334', 'System Analysis and Design', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '300 Level', 'first', 2, 'Elective.', '[]'::jsonb, 'Department of Statistics undergraduate course module'),
  ('MTH 441', 'Mathematical Methods II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'first', 3, 'Elective. Calculus of variations: Lagrange''s functional and associated density. Necessary condition for a weak relative extremum. Hamilton''s principle. Lagrange''s equations and geodesic problems. The Du Bois Raymond equation and corner conditions. Variable end points and related theorems. Sufficient conditions for a minimum, isoperimetric problems. Variational integral transforms. Laplace, Fourier and Hankel transforms. Complex variable methods; convolution theorems; applications to solutions of differential equations with initial/boundary conditions.', '["Calculus of variations: Lagrange''s functional and associated density", "Necessary condition for a weak relative extremum", "Hamilton''s principle", "Lagrange''s equations and geodesic problems", "The Du Bois Raymond equation and corner conditions", "Variable end points and related theorems", "Sufficient conditions for a minimum, isoperimetric problems", "Variational integral transforms", "Laplace, Fourier and Hankel transforms", "Complex variable methods", "Convolution theorems", "Applications to solutions of differential equations with initial/boundary conditions"]'::jsonb, 'Department of Statistics undergraduate course module'),
  ('CED 342', 'Business Development and Management', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'second', 2, '', '[]'::jsonb, 'Department of Statistics undergraduate course module'),
  ('MTH 322', 'Elements of Differential Equations II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Statistics', '400 Level', 'second', 3, 'Elective. Series solution of second-order differential equations. Sturm-Liouville problems. Orthogonal polynomials and functions. Fourier series, Fourier-Bessel and Fourier-Legendre series. Fourier transformation, solution of Laplace, wave and heat equations by the Fourier method (separation of variables). Special functions: Gamma, Beta, Bessel, Legendre and Hypergeometric.', '["Series solution of second-order differential equations", "Sturm-Liouville problems", "Orthogonal polynomials and functions", "Fourier series, Fourier-Bessel and Fourier-Legendre series", "Fourier transformation, solution of Laplace, wave and heat equations by the Fourier method (separation of variables)", "Special functions: Gamma, Beta, Bessel, Legendre and Hypergeometric"]'::jsonb, 'Department of Statistics undergraduate course module');
